### Fixed Code Snippet

```java
import java.io.*;
import java.security.MessageDigest;

public class SecureDeserialization {
    // This method securely deserializes by validating the input
    public static Object deserialize(byte[] data, String expectedHash) throws IOException, ClassNotFoundException, NoSuchAlgorithmException {
        // Check the hash of the data before deserialization
        String actualHash = calculateHash(data);
        if (!actualHash.equals(expectedHash)) {
            throw new SecurityException("Data hash does not match expected hash.");
        }

        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return ois.readObject();
        }
    }

    // Calculates a SHA-256 hash of the data for integrity checking
    private static String calculateHash(byte[] data) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(data);
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0'); // Pad to two digits
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public static void main(String[] args) throws IOException, ClassNotFoundException, NoSuchAlgorithmException {
        // Simulating deserialization from an untrusted source
        byte[] safeData = getTrustedData(); // Assume this comes from a trusted source
        String expectedHash = "expected_sha256_hash_of_safeData"; // Should be precomputed and known
        Object obj = deserialize(safeData, expectedHash);
        System.out.println("Securely deserialized object: " + obj);
    }

    // Simulated method to get safe data
    private static byte[] getTrustedData() {
        // In a real scenario, this would be a trusted serialized object
        return new byte[0];
    }
}
```

